BEGIN;
  CREATE TABLE books(id TEXT PRIMARY KEY,title TEXT NOT NULL,author TEXT NOT NULL DEFAULT '',language TEXT NOT NULL DEFAULT 'zh',format TEXT NOT NULL,category TEXT NOT NULL DEFAULT '未分类',cover TEXT,hash TEXT UNIQUE NOT NULL,file_path TEXT NOT NULL,warning TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
  CREATE TABLE chapters(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,title TEXT NOT NULL,ordinal INTEGER NOT NULL,href TEXT NOT NULL DEFAULT '',page INTEGER,UNIQUE(book_id,ordinal));
  CREATE TABLE passages(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,seq INTEGER NOT NULL,ordinal INTEGER NOT NULL,text TEXT NOT NULL,location TEXT NOT NULL,page INTEGER,hash TEXT NOT NULL,UNIQUE(book_id,seq));
  CREATE INDEX passage_chapter ON passages(chapter_id,ordinal);
  CREATE TABLE reading_progress(book_id TEXT PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE,seq INTEGER NOT NULL DEFAULT 0,offset INTEGER NOT NULL DEFAULT 0,chapter_id TEXT,location TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
  CREATE TABLE bookmarks(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,passage_id TEXT REFERENCES passages(id) ON DELETE CASCADE,label TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
  CREATE TABLE highlights(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,passage_id TEXT NOT NULL REFERENCES passages(id) ON DELETE CASCADE,quote TEXT NOT NULL,color TEXT NOT NULL DEFAULT 'gold',created_at TEXT NOT NULL);
  CREATE TABLE notes(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE SET NULL,passage_id TEXT REFERENCES passages(id) ON DELETE SET NULL,kind TEXT NOT NULL,content TEXT NOT NULL,quote TEXT NOT NULL DEFAULT '',topic TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
  CREATE TABLE concepts(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL);
  CREATE TABLE book_concepts(book_id TEXT REFERENCES books(id) ON DELETE CASCADE,concept_id TEXT REFERENCES concepts(id) ON DELETE CASCADE,PRIMARY KEY(book_id,concept_id));
  CREATE TABLE conversations(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE CASCADE,title TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,citations TEXT NOT NULL DEFAULT '[]',professor TEXT NOT NULL DEFAULT '',ceiling INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
  CREATE TABLE debates(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,topic TEXT NOT NULL,professor_a TEXT NOT NULL,professor_b TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'paused',scope TEXT NOT NULL DEFAULT 'strict',created_at TEXT NOT NULL);
  CREATE TABLE debate_turns(id TEXT PRIMARY KEY,debate_id TEXT NOT NULL REFERENCES debates(id) ON DELETE CASCADE,role TEXT NOT NULL,professor TEXT NOT NULL,content TEXT NOT NULL,citations TEXT NOT NULL DEFAULT '[]',ceiling INTEGER NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE research_topics(id TEXT PRIMARY KEY,title TEXT NOT NULL,book_ids TEXT NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE research_documents(id TEXT PRIMARY KEY,topic_id TEXT REFERENCES research_topics(id) ON DELETE CASCADE,title TEXT NOT NULL,content TEXT NOT NULL,citations TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
  CREATE TABLE vocabulary(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE SET NULL,passage_id TEXT REFERENCES passages(id) ON DELETE SET NULL,word TEXT NOT NULL,meaning TEXT NOT NULL,example TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
  CREATE TABLE analysis_jobs(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
  CREATE TABLE embeddings(hash TEXT NOT NULL,model TEXT NOT NULL,vector TEXT NOT NULL,PRIMARY KEY(hash,model));
  CREATE TABLE summaries(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE CASCADE,chapter_id TEXT REFERENCES chapters(id) ON DELETE CASCADE,level TEXT NOT NULL,ceiling INTEGER NOT NULL,content TEXT NOT NULL);
  CREATE TABLE audio_cache(id TEXT PRIMARY KEY,text_hash TEXT NOT NULL,voice TEXT NOT NULL,model TEXT NOT NULL,file_path TEXT NOT NULL,passage_id TEXT REFERENCES passages(id) ON DELETE SET NULL,created_at TEXT NOT NULL);
  CREATE TABLE user_viewpoints(id TEXT PRIMARY KEY,topic TEXT NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE viewpoint_history(id TEXT PRIMARY KEY,viewpoint_id TEXT NOT NULL REFERENCES user_viewpoints(id) ON DELETE CASCADE,book_id TEXT REFERENCES books(id) ON DELETE SET NULL,content TEXT NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE reading_history(id TEXT PRIMARY KEY,book_id TEXT REFERENCES books(id) ON DELETE CASCADE,seq INTEGER NOT NULL,created_at TEXT NOT NULL);
  CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
  CREATE TABLE usage_log(id TEXT PRIMARY KEY,task TEXT NOT NULL,model TEXT NOT NULL,input_tokens INTEGER NOT NULL,output_tokens INTEGER NOT NULL,created_at TEXT NOT NULL);
  CREATE VIRTUAL TABLE passage_fts USING fts5(passage_id UNINDEXED,text,tokenize='trigram');
  CREATE TRIGGER passages_ai AFTER INSERT ON passages BEGIN INSERT INTO passage_fts(passage_id,text) VALUES(new.id,new.text); END;
  CREATE TRIGGER passages_ad AFTER DELETE ON passages BEGIN DELETE FROM passage_fts WHERE passage_id=old.id; END;
  CREATE TRIGGER passages_au AFTER UPDATE OF text ON passages BEGIN DELETE FROM passage_fts WHERE passage_id=old.id; INSERT INTO passage_fts(passage_id,text) VALUES(new.id,new.text); END;
  PRAGMA user_version=1; COMMIT;
